probeProgram:
using System.Diagnostics;
using System.Text.Json;
using OfficeIMO.PowerPoint;

if (args.Contains("--tables")) {
    var samples = new List<object>();
    for (int pass = 0; pass < 4; pass++) {
        using var presentation = PowerPointDocument.Create();
        var slide = presentation.AddSlide();
        long before = GC.GetAllocatedBytesForCurrentThread();
        var watch = Stopwatch.StartNew();
        for (int index = 0; index < 20; index++) slide.AddTable(10, 10, OfficeIMO.OfficeLength.Points(30), OfficeIMO.OfficeLength.Points(30), OfficeIMO.OfficeLength.Points(600), OfficeIMO.OfficeLength.Points(400));
        watch.Stop();
        samples.Add(new { pass, millisecondsPerTable = watch.Elapsed.TotalMilliseconds / 20, allocatedBytesPerTable = (GC.GetAllocatedBytesForCurrentThread() - before) / 20 });
        using var output = new MemoryStream();
        presentation.Save(output);
        using var reopened = PowerPointDocument.Load(output);
        var tables = reopened.Slides[0].Tables.ToArray();
        if (tables.Length != 20 || tables.Any(t => t.Rows != 10 || t.Columns != 10 || t.GetCell(0, 0).Text != "") || reopened.ValidateDocument().Any()) throw new InvalidOperationException("Table package validation failed.");
    }
    Console.WriteLine(JsonSerializer.Serialize(new { samples, validation = "Passed" }));
    return;
}
var measurements = new List<object>();
void Run(string mode, int count) {
    long before = GC.GetAllocatedBytesForCurrentThread();
    var watch = Stopwatch.StartNew();
    for (int index = 0; index < count; index++) {
        using var presentation = PowerPointDocument.Create();
        if (presentation.Slides.Count != 0) throw new InvalidOperationException("Unexpected initial slide.");
    }
    watch.Stop();
    measurements.Add(new { mode, count, milliseconds = watch.Elapsed.TotalMilliseconds / count, allocatedBytes = (GC.GetAllocatedBytesForCurrentThread() - before) / count });
}
Run("cold", 1);
for (int i = 0; i < 12; i++) { using var presentation = PowerPointDocument.Create(); }
for (int i = 0; i < 3; i++) Run("warm", 100);
using (var presentation = PowerPointDocument.Create()) {
    presentation.AddSlide().AddTitle("Creation proof");
    using var output = new MemoryStream();
    presentation.Save(output);
    using var reopened = PowerPointDocument.Load(output);
    if (reopened.Slides.Count != 1 || reopened.Slides[0].TextBoxes.First().Text != "Creation proof" || reopened.ValidateDocument().Any()) throw new InvalidOperationException("Saved presentation contract failed.");
}
Console.WriteLine(JsonSerializer.Serialize(new { framework = System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription, measurements, validation = "Passed" }));
